def caesar_cipher_1(text, shift):
    res = []
    for c in text:
        if c.isalpha():
            base = ord('a') if c.islower() else ord('A')
            res.append(chr((ord(c) - base + shift) % 26 + base))
        else:
            res.append(c)
    return ''.join(res)

